@Service
@RequiredArgsConstructor
class RepoClient {

    private final DetailRepository detailRepository;

    public EventDocument save(EventDocument documentToSave) {
        return detailRepository.save(documentToSave);
    }
}

@Builder
@Getter
@EqualsAndHashCode
@ToString
final class IssueRecursion implements Comparable<IssueRecursion>{

  private final String name;

  @Override
  public int compareTo(IssueRecursion issue) {
    return name.compareTo(issue.getName());
  }
}

