import org.springframework.boot.json.JsonParser;
import java.util.*;
import my.app.Context;

public class Deserializer {

    public Map deserialize(JsonParser p, Context c) {
        return getTarget();
    }

    public Map deserialize(JsonParser p) {
        Context c = new Context();
        return this.deserialize(p, c); // <- false positive
    }
}

public class Deserializer {

    public Map deserialize(JsonParser p, Context c) {
        return getTarget();
    }

    public Map deserialize(JsonParser p, String str) {
        Context c = new Context();
        return this.deserialize(p, str); // bad
    }
}

